var VERSION = "1.0.0";
var NOTES = [-1, 36, 38, 43, 47, 50, 37, 39, 42, 46, 49, 51, -1, -1, -1, -1]; // AC = accent

var pats = [], plen = [];
for (var p = 0; p < NP; p++) { pats.push(emptyPat()); plen.push(16); }
